"""Portable analysis of a frozen public-flow-study run; no simulation or tuning."""
import json,sys,math,random,statistics,html
from pathlib import Path
from collections import Counter,defaultdict
D=Path(sys.argv[1]); rows=[json.loads(l) for l in (D/'games.jsonl').read_text().splitlines()]; good=[r for r in rows if r['status']=='complete']; manifest=json.loads((D/'manifest.json').read_text()); names=json.loads((D/'components.json').read_text())
mean=lambda a:statistics.mean(a) if a else 0
pct=lambda n,d:f'{100*n/d:.1f}%' if d else '—'
def q(a,p):
 a=sorted(a);return a[min(len(a)-1,math.ceil(p*len(a))-1)] if a else 0
def dist(a):return {'mean':mean(a),'p10':q(a,.1),'median':q(a,.5),'p90':q(a,.9),'max':max(a,default=0)}
def ci(rs,key):
 groups=defaultdict(list)
 for r in rs:groups[r['seed']].append(key(r))
 a=[mean(v) for v in groups.values()];rng=random.Random(147);b=[mean(rng.choices(a,k=len(a))) for _ in range(1500)]
 return [q(b,.025),q(b,.975)]
def fm(n):return f'{n:.1f}'
def table(head,body):return '<table><thead><tr>'+''.join('<th>'+str(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in r)+'</tr>' for r in body)+'</tbody></table>'
summary={}; main=[]; diagnostics=[]; duration=[]; economics=[]
for n in [2,3,4]:
 r=[x for x in good if x['players']==n]; cap=[x for x in r if x['endReason']=='roundLimit'];fin=[x for x in r if x['endReason']=='finish'];prices=[p for x in r for p in x['prices']]
 summary[n]={'n':len(r),'finish':len(fin),'cap':len(cap),'spread':dist([x['spread'] for x in r]),'spreadFinish':dist([x['spread'] for x in fin]),'spreadCap':dist([x['spread'] for x in cap]),'prices':dist(prices),'rounds':dist([x['rounds'] for x in r]),'spreadCI':ci(r,lambda x:x['spread']),'capCI':ci(r,lambda x:x['endReason']=='roundLimit'),'noSales':sum(x['noSales'] for x in r),'auctions':sum(x['auctions'] for x in r)}
 z=summary[n];main.append([n,len(r),pct(len(fin),len(r)),pct(len(cap),len(r)),fm(z['spread']['mean']),f"{z['spread']['median']} / {z['spread']['p90']}",fm(mean([x['topThreeGap'] for x in r])),f"${mean(prices):.2f}"])
 diagnostics.append([n,len(cap),fm(mean([max(x['positions']) for x in cap])),fm(mean([x['remainingDeck'] for x in cap])),fm(mean([x['rolls'] for x in cap])),fm(mean([x['recoveryDiscards'] for x in cap])),fm(mean([x['recoveryPrinted'] for x in cap])),fm(mean([x['noSales'] for x in cap]))])
 duration.append([n,f"{z['rounds']['mean']:.2f}",f"{z['rounds']['median']} / {z['rounds']['p90']}",fm(mean([x['auctions'] for x in r])),fm(mean([sum(v for k,v in x['actions'].items() if k!='call') for x in r])),fm(mean([len(x['values']) for x in r])),fm(mean([x['bankCards'] for x in r]))])
 economics.append([n,len(prices),f"${mean(prices):.2f}",f"${q(prices,.1)} / ${q(prices,.5)} / ${q(prices,.9)}",pct(prices.count(1),len(prices)),pct(sum(x['noSales'] for x in r),sum(x['auctions'] for x in r))])
values=Counter(k for r in good for k in r['values']);exposures=Counter(k for r in good for k in r['valueExposures'] if k);founders=defaultdict(lambda:Counter())
for r in good:
 for f in r['founders']:founders[str(f)]['finalCompanies']+=1
 for f in r['founderHires']:founders[str(f)]['hires']+=1
 for f,v in r['founderMovement'].items():founders[f].update(v)
(D/'summary.json').write_text(json.dumps(summary,indent=2))
(D/'metric-registry.json').write_text(json.dumps({'revision':1,'spread':'max final position minus min final position; spaces/game; completed games; lower desired, no approved numerical threshold','finish':'endReason finish / complete games; first crossing24, finish whole reveal','cap':'endReason roundLimit / complete games; distinguish from finishes in round7','prices':'paid dollars per sold auction; no-sale excluded; extra auctions included unless labelled normal','valueExposure':'card held at each logged support action; repeated opportunities, not distinct cards or legal plays','founderMovement':'engine-attributed forward/backward steps; overlapping reaction credit, not additive causal contribution','uncertainty':'1500 fixed-seed bootstrap draws of whole seed clusters (self+mixed), 60 independent seed clusters/player count','targets':'100% completion; zero invariant/replay errors; tightness/price thresholds not fixed; do not label balance passed'},indent=2))
reviews=json.loads((D/'sample-reviews.json').read_text()) if (D/'sample-reviews.json').exists() else []
styles='body{font:17px/1.55 system-ui;max-width:1120px;margin:40px auto;padding:0 24px;color:#222;background:#fbfaf6}h1{font-size:38px;line-height:1.1}h2{margin-top:40px}table{border-collapse:collapse;width:100%;font-size:15px;background:white}th,td{padding:9px;text-align:left;border-bottom:1px solid #ddd}th{background:#e5ece7}a{color:#25644c}.lead{font-size:21px}.note{background:#fff0c5;padding:16px}details{margin:16px 0}article{border-top:1px solid #aaa;padding:12px 0}code{overflow-wrap:anywhere}.bar{display:inline-block;background:#588d76;height:14px;vertical-align:middle}nav{display:flex;gap:18px;flex-wrap:wrap}small{color:#555}'
body=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Vests v147 · full study</title><style>{styles}</style><h1>What stops the race reaching 24?</h1><p class="lead">{len(rows)} games · v{manifest['version']} · {D.name} · 2–4 players · all founders and values</p><nav><a href="#results">Race spread</a><a href="#cap">Seven-round cap</a><a href="#prices">Auctions</a><a href="#cards">Card usage</a><a href="#reviews">Ten replays</a></nav><p>This tests the approved rules, not a tuned replacement: eight cards per company, N+1 public row, three private values, one copy each, sequential dice, dilution, all 26 active founders, and a seven-round cap. Harry rolls one bland die; Mura rolls one mild die. Convertible Notes draws two row cards after discarding one; Board Coup discards a row card for leadership.</p><h2 id="results">Results by player count</h2>'''
body+=table(['Players','Games','Reached 24','Cap exit','Mean spread','Spread median / p90','Top-three gap','Mean paid'],main)
body+='<p>Spread is first minus last at settlement. A company may reach 24 and subsequently retreat: finish records any crossing during the completed round. Cap exits are not failed simulations. Small spread in a capped game does not establish that the pacing works.</p>'
body+=table(['Players','Mean spread when reached 24','Mean spread at cap','95% interval for mean spread','95% interval for cap rate'],[[n,fm(summary[n]['spreadFinish']['mean']),fm(summary[n]['spreadCap']['mean']),'–'.join(fm(x) for x in summary[n]['spreadCI']),'–'.join(f'{100*x:.1f}%' for x in summary[n]['capCI'])] for n in summary])
body+='<h2 id="cap">Why the seven-round cap binds</h2><p><b>1. The base movement budget is low, especially with two players.</b> Both dice have 7/6 printed movement per roll; a mild × contributes zero before its recovery cost. One ordinary two-die funding therefore supplies 7/3 ≈ 2.33 printed spaces—not three—even before recovery. With six companies, a seven-round N+1 row supplies only 21 / 28 / 35 card opportunities at 2 / 3 / 4 players. Uniformly spread, that is about 8.17 / 10.89 / 13.61 printed spaces per company, plus setup, before founders/cards/catch-up. The finish requires 23 spaces from the starting position.</p><p><b>2. Eight cards is supply, not a promise that eight will appear.</b> The cap arrives while a substantial part of the deck remains. Scarcity limits repeated funding but does not create the missing movement. Returning cards with Reid can also recycle selected companies and delay unseen cards.</p>'
body+=table(['Players','Capped games','Mean leader at cap','Cards left in deck','Dice rolled','Recovery discards','Printed spaces lost to recovery','No-sales'],diagnostics)
body+='<p><b>3. Fumbles consume later rolls; zeros consume opportunities.</b> Recovery discards above include all die sources. Lost printed spaces are the actual numbered faces discarded, not a counterfactual estimate of how much further the race would finish. Founder chains can offset or amplify those losses.</p><p><b>4. Some actions deliberately suppress movement.</b> Illicit Funding retreats 3 for a $20 obligation reduction; Secondary Sale and Sweat Equity retreat 2; Reid retreats 2; Ryan and Lei can cause recovery losses. These can be sensible investor choices even when they postpone a finish. Catch-up moves the last-place companies, so it does not push an already leading company toward 24.</p><p><b>5. The bots still distort some outcomes.</b> The bidders share a deterministic valuation heuristic, making many identical bids and caller tie wins. They use rough terminal prices, not multi-round rollout search. Late zero bids can remove funding altogether; extra-auction cards can sell for $1 without generating growth. Inspect the auction table and replay evidence before treating cheap shares or card popularity as a rule verdict.</p>'
body+='<h2>Length and action usage</h2>'+table(['Players','Mean rounds','Median / p90','Auctions/game','Support choices/game','Values/game','Bank cards/game'],duration)
body+='<p>Counts measure game operations, not human minutes. Support choices include passes and extra actions from Working Weekend; bids, die selections and founder responses add further decisions.</p>'
body+=table(['Players','Capital calls','Value actions','Founder changes','Passes'],[[n]+[fm(mean([r['actions'][k] for r in good if r['players']==n])) for k in ['raiseMoney','valueAction','changeFounder','passAction']] for n in [2,3,4]])
body+='<h2 id="prices">Auction prices</h2>'+table(['Players','Sold auctions','Mean paid','p10 / median / p90','$1 sales','No-sale rate'],economics)
body+='<p>Paid price, not maximum bid. Sold auctions include Rights Issue and Sealed Tender. The aggregate records do not retain auction mode, so a separate ordinary-fundraising average is not reported. Bank funding does not issue a share and is excluded. Prices from auctions in the same game are dependent; no per-auction independent confidence interval is claimed.</p>'
for n in [2,3,4]:
 prices=[p for r in good if r['players']==n for p in r['prices']]; bins=[('1',sum(x==1 for x in prices)),('2–4',sum(2<=x<=4 for x in prices)),('5–9',sum(5<=x<=9 for x in prices)),('10–19',sum(10<=x<=19 for x in prices)),('20+',sum(x>=20 for x in prices))]
 body+=f'<h3>{n} players · paid-price distribution</h3>'+table(['Price','Sold auctions','Share'],[[k,v,f'<span class="bar" style="width:{200*v/max(1,len(prices))}px"></span> {pct(v,len(prices))}'] for k,v in bins])
body+='<h2 id="cards">All value cards</h2><p>Exposure = a card held at a logged support opportunity, counted again if retained. It does not mean the card had a legal or worthwhile target. Usage is bot behavior, not an estimate of intrinsic card strength.</p>'
body+=table(['Card','Held opportunities','Plays','Plays/game'],[[html.escape(v['name']),exposures[k],values[k],f'{values[k]/len(good):.2f}'] for k,v in names['values'].items()])
body+='<details><summary>All founders: final presence, hires and attributed movement</summary><p>Final presence misses founders replaced earlier. Hires include value-card changes. Movement credit may overlap across reactions; do not sum columns as disjoint causes. Immediate founder dice are not included in founder movement credit, so Mura/Harry’s movement column understates their activity.</p>'+table(['Founder','Final company appearances','Hires','Forward credit','Backward credit'],[[f['name'],founders[str(f['id'])]['finalCompanies'],founders[str(f['id'])]['hires'],founders[str(f['id'])]['forward'],founders[str(f['id'])]['backward']] for f in names['founders']])+'</details>'
body+='<h2>Mixed-policy comparison</h2><p>Concentration and diversification use identical bid/support heuristics and differ mainly in row selection. This is a narrow policy comparison, not an expert diversification agent. Seeds alternate seat assignment; tied winners split one win credit.</p>'
policy=[]
for n in [2,3,4]:
 for pol in ['concentration','diversification']:
  seats=[(r,i) for r in good if r['players']==n and r['cohort']=='mixed' for i,p in enumerate(r['policies']) if p==pol]; credit=sum(1/len(r['winners']) for r,i in seats if i in r['winners']);policy.append([n,pol,len(seats),pct(credit,len(seats)),fm(mean([r['scores'][i] for r,i in seats]))])
body+=table(['Players','Policy','Seat-games','Split win rate','Mean score'],policy)
body+='<h2>Smallest useful next experiments</h2><ol><li>Keep rules fixed and vary only the round cap (7 vs 9), stratified by player count. Measure reaches-24 and spread among finishes separately.</li><li>Test extra bank funding at low player counts, rather than globally increasing dice variance. This directly addresses the lower number of public cards per six companies.</li><li>Separately test bank funding of no-sale cards. That isolates growth removed by auction valuation from the intended deck scarcity.</li><li>Improve the auction forecast and card evaluator before tuning around low use of a card. Keep a fixed-policy control so bot improvements are not mistaken for rules improvements.</li></ol><p>No proposed experiment above was silently applied to the playable rules.</p>'
body+='<h2 id="reviews">Ten complete replay reviews</h2><p>Preselected self-play seeds 4101–4103 for each player count, plus 4104 at four players. All full chronological traces were reviewed, including changes after the timing fix. Event indices are zero-based; company IDs follow Gogol, Amazin, Weta, Novidia, Testra, Obenay.</p>'
for review in reviews:
 r=next(r for r in good if r.get('sample')=='samples/'+review['game']+'.json');body+=f'<article><h3>{review["game"]} · {r["rounds"]} rounds · {r["endReason"]}</h3><p>Positions {r["positions"]}; scores {r["scores"]}.</p><p>{html.escape(review["review"])}</p><a href="samples/{review["game"]}.json">Full commands, decisions and events</a> · <a href="samples/{review["game"]}.compact.txt">Chronological review transcript</a></article>'
body+=f'<h2>Reliability and reproduction</h2><p>{len(good)}/{len(rows)} completed; {sum(r["status"]=="failed" for r in rows)} failed; {sum(r["status"]=="censored" for r in rows)} censored. Invariants run after every command. Ten independent replay checks compare complete logs and scores. Run-01 had a Reid forecast defect; run-02 revealed a duplicate power reset. Both are retained and excluded. The earlier v146 cohort used different components/setup and is not a controlled baseline.</p><p>60 fixed seeds × 3 player counts × 2 cohorts = 360 planned games. Confidence intervals cluster both cohorts by setup seed. Bots enumerate four ordered die pairs through founder resolution; newly restored random founder dice use a deterministic public-state forecast seed, not the real hidden RNG. Auctions use a bounded terminal-value heuristic. Results apply to these policies, not optimal humans. No human play-time or enjoyment claim is made.</p><p><code>node scripts/public-flow-study.js NEW_DIRECTORY</code><br>Analysis: <code>python3 scripts/current-dice-report.py {D}</code></p><p><a href="manifest.json">Frozen protocol</a> · <a href="games.jsonl">All games</a> · <a href="summary.json">Summary data</a> · <a href="metric-registry.json">Metric definitions</a> · <a href="sample-reviews.json">Reviews</a> · <a href="source/src/live-dice-engine.js">Frozen engine</a> · <a href="runtime.json">Runtime</a></p><small>Source SHA-256: {manifest["source"]}. Report/metric registry are post-run analysis artifacts; simulation source and rules were frozen before the run. UI-only follow-up changes do not alter the simulated rules.</small></html>'
(D/'report.html').write_text(body)
print(json.dumps(summary,indent=2))
